<html lang="en">
<head>
<meta charset="utf-8">
<title>Theme persistence</title>
<script>
  // Applies the stored theme before first paint to avoid a flash.
  (function () {
    try {
      var t = localStorage.getItem('theme');
      if (t === 'light' || t === 'dark') {
        document.documentElement.setAttribute('data-theme', t);
      }
      // system (or anything else): leave attribute absent
    } catch (e) { /* storage unavailable */ }
  })();
</script>
<style>
  :root { --bg: #ffffff; --fg: #111111; }
  html[data-theme='dark'] { --bg: #1a1a2e; --fg: #eaeaea; }
  @media (prefers-color-scheme: dark) {
    html:not([data-theme]) { --bg: #101020; --fg: #f0f0f0; }
  }
  body { background: var(--bg); color: var(--fg); font-family: sans-serif; padding: 2rem; }
  label { margin-right: 1rem; }
</style>
</head>
<body>
<h1>Three-way theme control</h1>
<fieldset>
  <legend>Theme</legend>
  <label><input type="radio" name="theme" value="light"> Light</label>
  <label><input type="radio" name="theme" value="dark"> Dark</label>
  <label><input type="radio" name="theme" value="system"> System</label>
</fieldset>

