const { test, expect } = require('@playwright/test');

test.describe('theme toggle persists across reload', () => {
  test('pick dark, reload, dark persists', async ({ page }) => {
    await page.goto('/');

    await page.check('input[name="theme"][value="dark"]');
    await expect(page.locator('html')).toHaveAttribute('data-theme', 'dark');

    await page.reload();

    // Attribute must already be set by the inline head script.
    const attrBeforePaint = await page.evaluate(() => document.documentElement.getAttribute('data-theme'));
    expect(attrBeforePaint).toBe('dark');

    await expect(page.locator('html')).toHaveAttribute('data-theme', 'dark');
    await expect(page.locator('input[name="theme"][value="dark"]')).toBeChecked();
  });

  test('switch to system, reload, no data-theme attribute', async ({ page }) => {
    await page.goto('/');
    await page.check('input[name="theme"][value="dark"]');

    await page.check('input[name="theme"][value="system"]');
    await expect(page.locator('html')).not.toHaveAttribute('data-theme');

    await page.reload();

    const attrBeforePaint = await page.evaluate(() => document.documentElement.getAttribute('data-theme'));
    expect(attrBeforePaint).toBeNull();
  });

  test('localStorage contents', async ({ page }) => {
    await page.goto('/');
    await page.check('input[name="theme"][value="light"]');

    let stored = await page.evaluate(() => localStorage.getItem('theme'));
    expect(stored).toBe('light');

    await page.check('input[name="theme"][value="system"]');
    stored = await page.evaluate(() => localStorage.getItem('theme'));
    expect(stored).toBe('system');

    await page.check('input[name="theme"][value="dark"]');
    await page.reload();
    stored = await page.evaluate(() => localStorage.getItem('theme'));
    expect(stored).toBe('dark');
  });
});

