'use strict';

const KEY = 'theme';

function apply(theme) {
  if (theme === 'light' || theme === 'dark') {
    document.documentElement.setAttribute('data-theme', theme);
  } else {
    // system: follow OS via CSS media query; remove explicit attribute
    document.documentElement.removeAttribute('data-theme');
  }
}

function current() {
  return document.querySelector('input[name="theme"]:checked')?.value ?? 'system';
}

function setChecked(value) {
  for (const input of document.querySelectorAll('input[name="theme"]')) {
    input.checked = input.value === value;
  }
}

document.addEventListener('change', (e) => {
  if (e.target.name !== 'theme') return;
  try { localStorage.setItem(KEY, e.target.value); } catch (_) {}
  apply(e.target.value);
});

// Restore control state on load (attribute itself is set by the inline head script).
try { setChecked(localStorage.getItem(KEY) || 'system'); } catch (_) {}

